inputs = ['zifvj', 'ghie', 'cxdh', 'cfbv', 'vbvyje']
outputs = ['zjzxwzxwj', 'zxwhie', 'yxdh', 'yueaxv', 'veaxvyje']

# Analyze each pair
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Let's look at character positions
    print(f"  Length: {len(inp)} -> {len(outp)}")

    # Find differences
    diff_positions = []
    for j in range(min(len(inp), len(outp))):
        if inp[j] != outp[j]:
            diff_positions.append((j, inp[j], outp[j]))

    if len(inp) != len(outp):
        # Check for insertions/deletions
        if len(inp) < len(outp):
            print(f"  Insertion detected (length increased by {len(outp) - len(inp)})")
        else:
            print(f"  Deletion detected (length decreased by {len(inp) - len(outp)})")

    if diff_positions:
        print(f"  Differences at positions: {diff_positions}")
    print()

